package net.wtworkshop.beeblock.gametest;
import java.nio.file.Path;import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.minecraft.world.item.*;import net.wtworkshop.tool.*;import net.wtworkshop.station.*;import net.wtworkshop.beeblock.*;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.ClientTickEvent;
@EventBusSubscriber(modid="wt_beeblock_workshop",value=Dist.CLIENT)
public final class BeeCapture {
 private static int frames,phase;private static boolean opened,checked;
 @SubscribeEvent public static void tick(ClientTickEvent.Post e){if(!System.getProperty("wt_workshop.previewMode","").equals("bee"))return;var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null)return;var target=System.getProperty("wt_workshop.capture","");if(target.isEmpty())return;if(!opened){if(!checked){checked=true;if(net.neoforged.fml.ModList.get().isLoaded("forestry"))mc.getSingleplayerServer().execute(()->verifyForestry(mc));}open();opened=true;return;}if(++frames==35){try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(Path.of(target.replace(".png","-"+phase+".png")));}catch(Exception ex){throw new RuntimeException(ex);}frames=0;if(++phase<3)open();else mc.stop();}}
 private static void verifyForestry(Minecraft mc){var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());for(String input:new String[]{"beeswax","honey_drop"}){var menu=new StationMenu(4,p.getInventory());menu.getSlot(4).set(WorkshopTool.create(ToolType.SWORD,ToolData.of("iron","wood","string")));var item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("forestry:"+input));menu.getSlot(5).set(new ItemStack(item,8));menu.clicked(0,0,net.minecraft.world.inventory.ClickType.PICKUP,p);var d=WorkshopTool.data(menu.getCarried());if(d==null||d.modifierLevel(input.equals("beeswax")?BeeWorkshop.WAXED:BeeWorkshop.HONEYBOUND)!=1||!menu.getSlot(4).getItem().isEmpty())throw new IllegalStateException("Real Forestry transaction failed");}org.slf4j.LoggerFactory.getLogger("WT Bee Workshop").info("Verified real connected-player Forestry beeswax and honey-drop station transactions");}
 private static void open(){var mc=Minecraft.getInstance();mc.options.hideGui=false;if(phase==2){mc.setScreen(new Matrix());return;}var menu=new StationMenu(0,mc.player.getInventory());menu.getSlot(4).set(WorkshopTool.create(phase==0?ToolType.PICKAXE:ToolType.SWORD,ToolData.of("iron","wood","string")));var ingredient=net.neoforged.fml.ModList.get().isLoaded("forestry")?net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse(phase==0?"forestry:beeswax":"forestry:honey_drop")):phase==0?Items.HONEYCOMB:Items.HONEY_BOTTLE;menu.getSlot(5).set(new ItemStack(ingredient,8));menu.getSlot(0).set(StationLogic.compute(menu.inputList(),mc.level).result());mc.setScreen(new net.wtworkshop.client.StationScreen(menu,mc.player.getInventory(),Component.literal("Bee Workshop")));}
 private static final class Matrix extends Screen {Matrix(){super(Component.literal("Bee modifier accents"));}
 @Override public void render(GuiGraphics g,int mx,int my,float delta){g.fill(0,0,width,height,0xff20282e);g.drawCenteredString(font,"BEE WORKSHOP / WAX AND HONEY",width/2,18,0xffead5aa);var labels=new String[]{"BASE","WAXED","HONEYBOUND","BOTH"};var types=new ToolType[]{ToolType.SWORD,ToolType.AXE,ToolType.BROAD_AXE};for(int col=0;col<4;col++){int x=width/2-240+col*130;g.drawCenteredString(font,labels[col],x+40,48,0xffead5aa);for(int row=0;row<3;row++){var d=ToolData.of("iron","wood","string");if((col&1)!=0)d=d.withAddonSlot(BeeWorkshop.WAXED,Modifier.Slot.UPGRADE).withModifierAdded(BeeWorkshop.WAXED);if((col&2)!=0)d=d.withAddonSlot(BeeWorkshop.HONEYBOUND,Modifier.Slot.ABILITY).withModifierAdded(BeeWorkshop.HONEYBOUND);var stack=WorkshopTool.create(types[row],d);int y=70+row*120;g.pose().pushPose();g.pose().translate(x,y,0);g.pose().scale(5,5,1);g.renderItem(stack,0,0);g.pose().popPose();g.renderItem(stack,x+32,y+86);}}}}
}
